import io.github.diodeme.ji.agent.*;
import io.github.diodeme.ji.ai.*;
import io.github.diodeme.ji.session.memory.*;
import io.github.diodeme.ji.host.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.HexFormat;
ModelProvider provider = request -> subscriber -> {};
var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore()).build();
var sessions = new SessionApplicationService(runtime);
var session = sessions.create(new ModelRef("faux", "model"), ".");
var sessionId = session.id();
session.close();
var hostStore = new MemoryHostStore();
var prompts = new PromptApplicationService(sessions, hostStore);
try { prompts.prompt(sessionId, "command-fails", "hello"); } catch (Exception failure) { System.out.println("PROMPT_FAILURE=" + failure.getClass().getName() + ":" + failure.getMessage()); }
var hash = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest("hello".getBytes(StandardCharsets.UTF_8)));
System.out.println("JOURNAL_PRESENT_AFTER_FAILURE=" + hostStore.command(sessionId, "command-fails", hash).isPresent());
sessions.close();
/exit
'@
